(4666516, 673235, 92807, '<td valign="top">The best wine you could get was sutter home? Just kidding, nice use of the older looking wine glasses</td>', 'The best wine you could get was sutter home? Just kidding, nice use of the older looking wine glasses', '2008-04-30 01:32:42.000000', NULL, 1),
(4666522, 674020, 3020, '<td valign="top">This looks like a fair attempt at Sepia however not knowing the process you used it appears you tried to Sepia color a color photograph instead of a black and white photo. The beak on the bird is too saturated compared to his white feathers imo.</td>', 'This looks like a fair attempt at Sepia however not knowing the process you used it appears you tried to Sepia color a color photograph instead of a black and white photo. The beak on the bird is too saturated compared to his white feathers imo.', '2008-04-30 01:34:14.000000', NULL, 1),
(4666548, 673903, 12661, '<td valign="top">Nice composition and good application of horizontal centering. I would have prefer more even lighting, especially in the bright background, but overall, it still works nicely.</td>', 'Nice composition and good application of horizontal centering. I would have prefer more even lighting, especially in the bright background, but overall, it still works nicely.', '2008-04-30 01:38:53.000000', NULL, 1),
(4666559, 673941, 12661, '<td valign="top">Nice job capturing the texture of the wood. The weathered age feel of the texture goes well with the sepia tone.</td>', 'Nice job capturing the texture of the wood. The weathered age feel of the texture goes well with the sepia tone.', '2008-04-30 01:41:15.000000', NULL, 1),
(4666563, 672309, 3020, '<td valign="top">This appears to be a tough shot, the shadows vs his white fur. Regardless I feel the exposure to be too high for the time of day the image appears to have been taken at and is causing his highlights to clip.</td>', 'This appears to be a tough shot, the shadows vs his white fur. Regardless I feel the exposure to be too high for the time of day the image appears to have been taken at and is causing his highlights to clip.', '2008-04-30 01:41:31.000000', NULL, 1),
(4666591, 673793, 33769, '<td valign="top">(8) -you may want to request your image be pulled- tho- since you added text and its against basic rules... goodluck!</td>', '(8) -you may want to request your image be pulled- tho- since you added text and its against basic rules... goodluck!', '2008-04-30 01:48:43.000000', NULL, 1),
(4666598, 673833, 12661, '<td valign="top">I like the full frame composition and the point of view. Placing the snout into the bottom corner worked well. I don''t generally care for pet photos, but you definitely captured a professional look on this one.</td>', 'I like the full frame composition and the point of view. Placing the snout into the bottom corner worked well. I don''t generally care for pet photos, but you definitely captured a professional look on this one.', '2008-04-30 01:50:08.000000', NULL, 1),
