INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4667571, 673225, 34134, '<td valign="top">This has a certain wonderful quality about it. Like it.</td>', 'This has a certain wonderful quality about it. Like it.', '2008-04-30 11:37:22.000000', NULL, 1),
(4667576, 673697, 34134, '<td valign="top">Good composition. Love the angle!</td>', 'Good composition. Love the angle!', '2008-04-30 11:38:59.000000', NULL, 1),
(4667593, 673990, 56828, '<td valign="top">(this was not taking into account when voting)...but it''s actually spelled Ma''am</td>', '(this was not taking into account when voting)...but it''s actually spelled Ma''am', '2008-04-30 11:47:53.000000', NULL, 1),
(4667595, 673306, 56828, '<td valign="top">The photo is very blurry in my opinion.</td>', 'The photo is very blurry in my opinion.', '2008-04-30 11:48:31.000000', NULL, 1),
(4667596, 672352, 51538, '<td valign="top">I like the composition.  But that colour - hard to call it any sort of tone - is really something else.  6 for the composition. 0 for the tone.</td>', 'I like the composition.  But that colour - hard to call it any sort of tone - is really something else.  6 for the composition. 0 for the tone.', '2008-04-30 11:49:18.000000', NULL, 1),
(4667598, 673323, 51538, '<td valign="top">Posterization in the background bokeh.  Otherwise I like the flower.</td>', 'Posterization in the background bokeh.  Otherwise I like the flower.', '2008-04-30 11:50:06.000000', NULL, 1),
(4667601, 672660, 92739, '<td valign="top">sepia? not imo. sorry 1</td>', 'sepia? not imo. sorry 1', '2008-04-30 11:51:23.000000', NULL, 1),
(4667604, 674584, 56828, '<td valign="top">Okay...I''m sure some people are voting you down for this, but i''m not.  It looks as if you didn''t add any color, but you didn''t do any changes (color-wise) in post processing either.  You took a great shot of a sepia toned boy.  I like it, i think it''s great thinking outside the box...and it fits the challenge descritpion (well except the overall sepia tone part, but i''m ignoring that part.)</td>', 'Okay...I''m sure some people are voting you down for this, but i''m not.  It looks as if you didn''t add any color, but you didn''t do any changes (color-wise) in post processing either.  You took a great shot of a sepia toned boy.  I like it, i think it''s great thinking outside the box...and it fits the challenge descritpion (well except the overall sepia tone part, but i''m ignoring that part.)', '2008-04-30 11:52:20.000000', NULL, 1),
(4667605, 673329, 87808, '<td valign="top">fabulous shot, I just can not see any sepia in it though:<br/> <br/>I gave you a 6 for this shot.  But it is bothering me, so I hope you do not mind, but I copied it and then changed it to black and white.  It did change colour in BW, but it is very very subtle, in fact there is such a minuet change in colour but it does have a hint of sepia in it.  I think most people are going to say it is BW and not enough sepia in it.  It is still a dramatic shot and you have clean sharp lines.  It is a great shot. It kept me interested enough, that I went and had to look at it again and again and then try to adjust it to BW.   Well done, I am revising my score to 8</td>', 'fabulous shot, I just can not see any sepia in it though: I gave you a 6 for this shot.  But it is bothering me, so I hope you do not mind, but I copied it and then changed it to black and white.  It did change colour in BW, but it is very very subtle, in fact there is such a minuet change in colour but it does have a hint of sepia in it.  I think most people are going to say it is BW and not enough sepia in it.  It is still a dramatic shot and you have clean sharp lines.  It is a great shot. It kept me interested enough, that I went and had to look at it again and again and then try to adjust it to BW.   Well done, I am revising my score to 8', '2008-04-30 11:52:31.000000', NULL, 1),
(4667609, 674582, 56828, '<td valign="top">I don''t think you did much of a sepia toning here as i can see the green in the leaves....but that could be my eyes playing tricks on me so i''m still giving it a 6.</td>', 'I don''t think you did much of a sepia toning here as i can see the green in the leaves....but that could be my eyes playing tricks on me so i''m still giving it a 6.', '2008-04-30 11:54:15.000000', NULL, 1),
(4667616, 673209, 92828, '<td valign="top">Excellent.</td>', 'Excellent.', '2008-04-30 11:55:10.000000', NULL, 1),
(4667618, 674359, 56828, '<td valign="top">This is a very interesting shot.  I kind of like the concept of drawing your model and then photographing the drawing.</td>', 'This is a very interesting shot.  I kind of like the concept of drawing your model and then photographing the drawing.', '2008-04-30 11:55:51.000000', NULL, 1),
(4667622, 672818, 90502, '<td valign="top">Don''t like the subject for Sepia but it is a great piture</td>', 'Don''t like the subject for Sepia but it is a great piture', '2008-04-30 11:57:01.000000', NULL, 1),
(4667624, 673871, 56828, '<td valign="top">The angle the photograph is taken at, makes you lose detail in the shape of the swan.  I couldn''t really tell where it was facing.</td>', 'The angle the photograph is taken at, makes you lose detail in the shape of the swan.  I couldn''t really tell where it was facing.', '2008-04-30 11:57:42.000000', NULL, 1),
