(4668722, 674498, 53416, '<td valign="top">Nice action capture, but am not keen on the composition.</td>', 'Nice action capture, but am not keen on the composition.', '2008-04-30 18:09:19.000000', NULL, 1),
(4668723, 674426, 70896, '<td valign="top">You need better lighting for this. More fill flash.  The shadow in the wall is very harsh, and there is no detail in her face. Also I dont like the angle.</td>', 'You need better lighting for this. More fill flash.  The shadow in the wall is very harsh, and there is no detail in her face. Also I dont like the angle.', '2008-04-30 18:09:22.000000', NULL, 1),
(4668727, 672409, 53416, '<td valign="top">I guess some may complain that this is not ''true sepia'' - but the subdued overall brown tint works for me.<br/> <br/>Sharp and with good detail, just not keen on the composition.</td>', 'I guess some may complain that this is not ''true sepia'' - but the subdued overall brown tint works for me. Sharp and with good detail, just not keen on the composition.', '2008-04-30 18:10:28.000000', NULL, 1),
(4668728, 674582, 91295, '<td valign="top">This is a gorgeous image, but I fear that many will see the slight colors still in the image (ie, the greens in the bouquet)  and not consider it a true "sepia" image even though it has a light sepia cast.</td>', 'This is a gorgeous image, but I fear that many will see the slight colors still in the image (ie, the greens in the bouquet)  and not consider it a true "sepia" image even though it has a light sepia cast.', '2008-04-30 18:10:46.000000', NULL, 1),
(4668729, 674057, 70896, '<td valign="top">There is nothing interesting about this photo. It lacks contrast. There are also too may elements that dont belong (door knob, bag on the right, the wall in the right, the piece of wood on the left)</td>', 'There is nothing interesting about this photo. It lacks contrast. There are also too may elements that dont belong (door knob, bag on the right, the wall in the right, the piece of wood on the left)', '2008-04-30 18:11:08.000000', NULL, 1),
(4668732, 674295, 53416, '<td valign="top">Ooh, nice - 70s style reminds me of pics of me at that age! Could be improved if the child''s arm was not obstructing their face.</td>', 'Ooh, nice - 70s style reminds me of pics of me at that age! Could be improved if the child''s arm was not obstructing their face.', '2008-04-30 18:12:42.000000', NULL, 1),
(4668737, 673242, 34627, '<td valign="top">I love macro work and this sepia portrait is a fine example. Good focust (sorry focus)exposure and cropping.</td>', 'I love macro work and this sepia portrait is a fine example. Good focust (sorry focus)exposure and cropping.', '2008-04-30 18:13:50.000000', NULL, 1),
(4668738, 674106, 53416, '<td valign="top">Too pinkish to be sepia.  Good texture and contrast though.</td>', 'Too pinkish to be sepia.  Good texture and contrast though.', '2008-04-30 18:13:56.000000', NULL, 1),
(4668740, 674324, 70896, '<td valign="top">I dont think her eyes look right for the rest of the pic. Its all very soft,  I really like the detail of her dress and the lighting (although its a bit dark). Her face just looks like it belongs to a completely different photo. Even the lighting seems different.</td>', 'I dont think her eyes look right for the rest of the pic. Its all very soft,  I really like the detail of her dress and the lighting (although its a bit dark). Her face just looks like it belongs to a completely different photo. Even the lighting seems different.', '2008-04-30 18:14:33.000000', NULL, 1),
(4668743, 673634, 53416, '<td valign="top">There doesn''t seem to be a real focal point, and the contrast is lacking.</td>', 'There doesn''t seem to be a real focal point, and the contrast is lacking.', '2008-04-30 18:14:57.000000', NULL, 1),
(4668744, 672296, 70896, '<td valign="top">OOF and not sepia enough for me.</td>', 'OOF and not sepia enough for me.', '2008-04-30 18:15:03.000000', NULL, 1),
(4668747, 673091, 34627, '<td valign="top">beautiful symetry and beautifully toned</td>', 'beautiful symetry and beautifully toned', '2008-04-30 18:15:31.000000', NULL, 1),
