(4668755, 672895, 90777, '<td valign="top">I''m sure the original of this image is really nice, but your processing seems to be a little overdone.</td>', 'I''m sure the original of this image is really nice, but your processing seems to be a little overdone.', '2008-04-30 18:18:03.000000', NULL, 1),
(4668756, 673198, 53416, '<td valign="top">Interesting lighting!  Good contrast and very crisp.</td>', 'Interesting lighting!  Good contrast and very crisp.', '2008-04-30 18:18:39.000000', NULL, 1),
(4668758, 672296, 90777, '<td valign="top">The image seems to be suffering from a little camera shake?</td>', 'The image seems to be suffering from a little camera shake?', '2008-04-30 18:19:15.000000', NULL, 1),
(4668759, 673043, 34627, '<td valign="top">a nice symetry, well toned and framed</td>', 'a nice symetry, well toned and framed', '2008-04-30 18:19:23.000000', NULL, 1),
(4668762, 673269, 70896, '<td valign="top">Its too sharp in my opinion, and it looks a bit too doctored. Its a nice image though.</td>', 'Its too sharp in my opinion, and it looks a bit too doctored. Its a nice image though.', '2008-04-30 18:19:36.000000', NULL, 1),
