INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4668799, 672645, 90777, '<td valign="top">Lovely Image, the bow in the hair and style of clothing along with the sepia really lends this a 1940''s feel</td>', 'Lovely Image, the bow in the hair and style of clothing along with the sepia really lends this a 1940''s feel', '2008-04-30 18:24:37.000000', NULL, 1),
