(4669941, 673121, 54645, '<td valign="top">top 5</td>', 'top 5', '2008-05-01 03:03:56.000000', NULL, 1),
(4669944, 674543, 54645, '<td valign="top">The shadow on the poor man giving up his life is forboding and ominous of things to come...or it just distracts from an otherwise lovely capture. Maybe a fill flash would help.</td>', 'The shadow on the poor man giving up his life is forboding and ominous of things to come...or it just distracts from an otherwise lovely capture. Maybe a fill flash would help.', '2008-05-01 03:06:31.000000', NULL, 1),
(4669949, 673696, 54645, '<td valign="top">I really like the composition you created, except for the tilting tower. I like the shadows which add to the various symmetry seen in architecture...good use of the light. My only nit pick if you want it is the perspective.</td>', 'I really like the composition you created, except for the tilting tower. I like the shadows which add to the various symmetry seen in architecture...good use of the light. My only nit pick if you want it is the perspective.', '2008-05-01 03:09:16.000000', NULL, 1),
(4669950, 673329, 54645, '<td valign="top">serious legs, nice use of light and conversion</td>', 'serious legs, nice use of light and conversion', '2008-05-01 03:09:43.000000', NULL, 1),
(4669951, 674447, 54645, '<td valign="top">I like this shot until I read the title</td>', 'I like this shot until I read the title', '2008-05-01 03:10:22.000000', NULL, 1),
(4669955, 674198, 54645, '<td valign="top">I don''t like the composition.</td>', 'I don''t like the composition.', '2008-05-01 03:11:31.000000', NULL, 1),
(4669958, 674584, 54645, '<td valign="top">I love this shot, great composition, sharp, bright eyes, I just don''t see the sepia toning. I''ll bite and give you a 6</td>', 'I love this shot, great composition, sharp, bright eyes, I just don''t see the sepia toning. I''ll bite and give you a 6', '2008-05-01 03:13:27.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4669961, 673043, 54645, '<td valign="top">over tinted imo</td>', 'over tinted imo', '2008-05-01 03:14:32.000000', NULL, 1),
(4669966, 673797, 54645, '<td valign="top">excellent composition and toning. I like the hint of grain. Top 10 for me. Well done.</td>', 'excellent composition and toning. I like the hint of grain. Top 10 for me. Well done.', '2008-05-01 03:15:39.000000', NULL, 1),
(4669991, 673233, 5364, '<td valign="top">I like the image, it''s a good idea, but I just feel that the chair doesn''t quite fit the theme - it''s too modern. I haven''t scored you lower because of that, but I might have scored you higher with a more period chair.</td>', 'I like the image, it''s a good idea, but I just feel that the chair doesn''t quite fit the theme - it''s too modern. I haven''t scored you lower because of that, but I might have scored you higher with a more period chair.', '2008-05-01 03:40:58.000000', NULL, 1),
(4669993, 673395, 5364, '<td valign="top">Nice idea, but I feel you''ve overdone the grain effect a bit.</td>', 'Nice idea, but I feel you''ve overdone the grain effect a bit.', '2008-05-01 03:42:20.000000', NULL, 1),
(4669996, 674305, 5364, '<td valign="top">Excellent idea and execution, I just wonder what it would look like having the arms entering the frame at an angle, rather than horizontally.</td>', 'Excellent idea and execution, I just wonder what it would look like having the arms entering the frame at an angle, rather than horizontally.', '2008-05-01 03:46:27.000000', NULL, 1),
(4670027, 674545, 88523, '<td valign="top">Very good shot..  Clever subject for sepia.</td>', 'Very good shot..  Clever subject for sepia.', '2008-05-01 04:36:41.000000', NULL, 1),
(4670028, 674342, 88523, '<td valign="top">Nice tones and textures in this shot.</td>', 'Nice tones and textures in this shot.', '2008-05-01 04:37:17.000000', NULL, 1),
(4670029, 673833, 88523, '<td valign="top">What a mug.  I like the diagonal..</td>', 'What a mug.  I like the diagonal..', '2008-05-01 04:37:50.000000', NULL, 1),
(4670030, 674264, 88523, '<td valign="top">I like the sense of depth the lights on the ceiling give  further down the coridor.</td>', 'I like the sense of depth the lights on the ceiling give  further down the coridor.', '2008-05-01 04:39:13.000000', NULL, 1),
(4670034, 673165, 88523, '<td valign="top">Very nice shot and depth of field.  The bricks a good for sepia and I like the way she comes out of the darkness.</td>', 'Very nice shot and depth of field.  The bricks a good for sepia and I like the way she comes out of the darkness.', '2008-05-01 04:41:49.000000', NULL, 1),
(4670035, 674179, 88523, '<td valign="top">I don''t think it fits the challenge b/c of use of colour... but still, very nice honest candid.</td>', 'I don''t think it fits the challenge b/c of use of colour... but still, very nice honest candid.', '2008-05-01 04:42:51.000000', NULL, 1),
(4670036, 674433, 88523, '<td valign="top">Nice portrait!  Great subjects.</td>', 'Nice portrait!  Great subjects.', '2008-05-01 04:43:48.000000', NULL, 1),
(4670037, 673321, 88523, '<td valign="top">Good shot!The angle shows their expertise...</td>', 'Good shot!The angle shows their expertise...', '2008-05-01 04:44:42.000000', NULL, 1),
(4670039, 674459, 88523, '<td valign="top">Awwwwwwwww..........Great!</td>', 'Awwwwwwwww..........Great!', '2008-05-01 04:45:05.000000', NULL, 1),
(4670040, 672856, 88523, '<td valign="top">Very good use of light. Very appropriate when doing a portrait of a photographer, huh?</td>', 'Very good use of light. Very appropriate when doing a portrait of a photographer, huh?', '2008-05-01 04:45:59.000000', NULL, 1),
(4670041, 674221, 88523, '<td valign="top">I think it must be difficult to make the mundane interesting, and always brave to try.  Even more so when confined by parameters like ''sepia''.  I like the shallow DOF.  I''m not entirely engaged though.</td>', 'I think it must be difficult to make the mundane interesting, and always brave to try.  Even more so when confined by parameters like ''sepia''.  I like the shallow DOF.  I''m not entirely engaged though.', '2008-05-01 04:49:09.000000', NULL, 1),
(4670043, 674466, 88523, '<td valign="top">You must have quite the lens to snap one of Mars....  I like the tones and the sepia brings out the harshness of the environment.</td>', 'You must have quite the lens to snap one of Mars....  I like the tones and the sepia brings out the harshness of the environment.', '2008-05-01 04:50:31.000000', NULL, 1),
(4670046, 673977, 88523, '<td valign="top">Great choice for Sepia...the mist lends itself very well...</td>', 'Great choice for Sepia...the mist lends itself very well...', '2008-05-01 04:52:59.000000', NULL, 1),
(4670048, 673427, 88523, '<td valign="top">Great angle and capture.</td>', 'Great angle and capture.', '2008-05-01 04:53:27.000000', NULL, 1),
(4670051, 673699, 88523, '<td valign="top">6...because I like shot which oozes with companionship, ...but mostly for the title.</td>', '6...because I like shot which oozes with companionship, ...but mostly for the title.', '2008-05-01 04:55:10.000000', NULL, 1),
(4670054, 672748, 88523, '<td valign="top">I am very curious as to what the cows perform...I really like this shot.</td>', 'I am very curious as to what the cows perform...I really like this shot.', '2008-05-01 04:56:07.000000', NULL, 1),
(4670056, 674210, 88523, '<td valign="top">Fantastic shot.  The bare hill with people and lone tree against the bright skies and kites is fantastic. Something kinda religious about it.</td>', 'Fantastic shot.  The bare hill with people and lone tree against the bright skies and kites is fantastic. Something kinda religious about it.', '2008-05-01 04:57:34.000000', NULL, 1),
(4670059, 674258, 88523, '<td valign="top">Nice portrait.  The light and sepia have created a pleasant softness...  (she''s quite pretty by the way)</td>', 'Nice portrait.  The light and sepia have created a pleasant softness...  (she''s quite pretty by the way)', '2008-05-01 04:59:13.000000', NULL, 1),
(4670152, 672812, 92498, '<td valign="top">Its a nice photo, but the manhole cover spoils it a bit. shame the person wasnt nearer the steps so you could have cropped the manhole cover out.</td>', 'Its a nice photo, but the manhole cover spoils it a bit. shame the person wasnt nearer the steps so you could have cropped the manhole cover out.', '2008-05-01 06:10:25.000000', NULL, 1),
(4670157, 674423, 92498, '<td valign="top">Nice photo, but its missing that special something. Maybe the whole photo is too sharp???</td>', 'Nice photo, but its missing that special something. Maybe the whole photo is too sharp???', '2008-05-01 06:12:16.000000', NULL, 1),
(4670166, 673650, 92498, '<td valign="top">it is a bit bright</td>', 'it is a bit bright', '2008-05-01 06:23:27.000000', NULL, 1),
(4670215, 674210, 39850, '<td valign="top">Nice compositional balance.  Like the sky, but wish a little more light to show the people more, which give a lot of interest to the image.</td>', 'Nice compositional balance.  Like the sky, but wish a little more light to show the people more, which give a lot of interest to the image.', '2008-05-01 07:20:54.000000', NULL, 1),
(4670224, 673745, 39850, '<td valign="top">Very nice.  Shame about the wheel on the right.</td>', 'Very nice.  Shame about the wheel on the right.', '2008-05-01 07:27:07.000000', NULL, 1),
(4670229, 674119, 39850, '<td valign="top">Nice capture.  Wish this was 640.  Tones work well.  Depending what you had to work with, perhaps a variation in composition.</td>', 'Nice capture.  Wish this was 640.  Tones work well.  Depending what you had to work with, perhaps a variation in composition.', '2008-05-01 07:29:08.000000', NULL, 1),
(4670243, 673639, 92498, '<td valign="top">i would have played with depth of field more.</td>', 'i would have played with depth of field more.', '2008-05-01 07:35:38.000000', NULL, 1),
(4670361, 672818, 61679, '<td valign="top">I never would have thought that sepia would work for this type of image.  It does!</td>', 'I never would have thought that sepia would work for this type of image.  It does!', '2008-05-01 08:45:38.000000', NULL, 1),
(4670371, 673527, 12661, '<td valign="top">Good use of brightness to get the most contrast in a monotone image. The focus is sharp and the DOF works well. This may even work with a centered composition.</td>', 'Good use of brightness to get the most contrast in a monotone image. The focus is sharp and the DOF works well. This may even work with a centered composition.', '2008-05-01 08:49:29.000000', NULL, 1),
(4670372, 673735, 12661, '<td valign="top">The darkness gives a nice nightlife sense to this image and the posture/facial expression capture the blues emotion. <br/> <br/>BTW, what instrument is that. I thought guitars had six strings and basses had four. I don''t think I have ever seen a 5-string.</td>', 'The darkness gives a nice nightlife sense to this image and the posture/facial expression capture the blues emotion.  BTW, what instrument is that. I thought guitars had six strings and basses had four. I don''t think I have ever seen a 5-string.', '2008-05-01 08:49:41.000000', NULL, 1),
(4670373, 673233, 12661, '<td valign="top">Nice job tying in the old fashion photo with an historic theme. The photo itself is well composed, clean of clutter, and well balanced.</td>', 'Nice job tying in the old fashion photo with an historic theme. The photo itself is well composed, clean of clutter, and well balanced.', '2008-05-01 08:49:45.000000', NULL, 1),
(4670376, 674334, 61679, '<td valign="top">You will probably get a few low votes for having color in this image but I think the sepia like tone over the color helps the artistic effect you were going for. Very creative. 7<br/> <br/>Back to bump:  The more I look at this image the more I like it.  This probably won''t make it on the front page but it does go into my favorites. 10</td>', 'You will probably get a few low votes for having color in this image but I think the sepia like tone over the color helps the artistic effect you were going for. Very creative. 7 Back to bump:  The more I look at this image the more I like it.  This probably won''t make it on the front page but it does go into my favorites. 10', '2008-05-01 08:51:38.000000', NULL, 1),
(4670379, 674056, 12661, '<td valign="top">Centering the single large clover was an excellent compositional decision. It breaks up the pattern wonderfully and ties together the entire image. If the crop was tighter, thereby cutting out the objects in the bottom left, the picture may have worked even better, at least in my eyes.</td>', 'Centering the single large clover was an excellent compositional decision. It breaks up the pattern wonderfully and ties together the entire image. If the crop was tighter, thereby cutting out the objects in the bottom left, the picture may have worked even better, at least in my eyes.', '2008-05-01 08:53:35.000000', NULL, 1),
(4670389, 672856, 61679, '<td valign="top">Back to comment and bump:  The lighting is expecptional and the sepia tone adds to the mood of the image.  My only suggestion is to crop some off the top and left to strengthen the limited negative space on the right. 9</td>', 'Back to comment and bump:  The lighting is expecptional and the sepia tone adds to the mood of the image.  My only suggestion is to crop some off the top and left to strengthen the limited negative space on the right. 9', '2008-05-01 08:59:11.000000', NULL, 1),
(4670393, 674285, 61679, '<td valign="top">Back to comment and bump: The sepia tone really enhances your image nicely.  The composition is wonderful and the lighting was perfect to bring out all of the delicate details. Nicely done. 9</td>', 'Back to comment and bump: The sepia tone really enhances your image nicely.  The composition is wonderful and the lighting was perfect to bring out all of the delicate details. Nicely done. 9', '2008-05-01 09:01:26.000000', NULL, 1),
(4670395, 673903, 61679, '<td valign="top">Back to comment and bump: The creativity of this image earns it space in my favorites.  Everything in this image works, the shallow depth of focus, the play between urban chic and urban decay.  The sepia tone pushes this beyond what b&amp;W could have achieved.  Nicely done. Bump 10</td>', 'Back to comment and bump: The creativity of this image earns it space in my favorites.  Everything in this image works, the shallow depth of focus, the play between urban chic and urban decay.  The sepia tone pushes this beyond what b&W could have achieved.  Nicely done. Bump 10', '2008-05-01 09:02:03.000000', NULL, 1),
(4670401, 673697, 61679, '<td valign="top">Back to comment and bump: You did a nice job with the exposure and post processing on this image.  Lots of nice angles to frame the subject and the lighting is dramatic and enhances the mode of the image.  Hope there is enough sepia to get you a 6+ score in this challenge. Bump to an 8.<br/> <br/>Back to bump again: I can''t justify giving this any score less than a 10.  This image has a very calming effect and has earned a spot in my favorites.</td>', 'Back to comment and bump: You did a nice job with the exposure and post processing on this image.  Lots of nice angles to frame the subject and the lighting is dramatic and enhances the mode of the image.  Hope there is enough sepia to get you a 6+ score in this challenge. Bump to an 8. Back to bump again: I can''t justify giving this any score less than a 10.  This image has a very calming effect and has earned a spot in my favorites.', '2008-05-01 09:05:36.000000', NULL, 1),
(4670408, 674552, 61679, '<td valign="top">Back to comment and bump: Love the title and the memories this image brings back.  A slight curve adjustment would help separate the subject from the background a bit more. 9</td>', 'Back to comment and bump: Love the title and the memories this image brings back.  A slight curve adjustment would help separate the subject from the background a bit more. 9', '2008-05-01 09:09:59.000000', NULL, 1),
(4670417, 674176, 61679, '<td valign="top">Back to comment and bump: The tonal range in the main subject is amazing.  A slight curve adjustment would help separate the "fiddle" from the background a bit more. 9</td>', 'Back to comment and bump: The tonal range in the main subject is amazing.  A slight curve adjustment would help separate the "fiddle" from the background a bit more. 9', '2008-05-01 09:13:42.000000', NULL, 1),
(4670419, 674554, 61679, '<td valign="top">Back to comment and bump: The sepia tone is very subtle in this image but any more might have been over the edge.  This is a fun image to look at and your creativity has earned you a new favorite. 10</td>', 'Back to comment and bump: The sepia tone is very subtle in this image but any more might have been over the edge.  This is a fun image to look at and your creativity has earned you a new favorite. 10', '2008-05-01 09:16:52.000000', NULL, 1),
(4670421, 674232, 61679, '<td valign="top">Bonus point for making me laugh. 7  Bumping to a 9.  Nice job.</td>', 'Bonus point for making me laugh. 7  Bumping to a 9.  Nice job.', '2008-05-01 09:17:22.000000', NULL, 1),
(4670467, 673571, 88492, '<td valign="top">looks very old.</td>', 'looks very old.', '2008-05-01 09:36:52.000000', NULL, 1),
(4670501, 673449, 73942, '<td valign="top">that''s such a sad picture, but nice sepia and I like the lighting of the bear  7</td>', 'that''s such a sad picture, but nice sepia and I like the lighting of the bear  7', '2008-05-01 09:50:11.000000', NULL, 1),
(4670526, 674228, 88492, '<td valign="top">don''t like the border</td>', 'don''t like the border', '2008-05-01 09:56:40.000000', NULL, 1),
(4670531, 674210, 70661, '<td valign="top">Wow..I really like this.</td>', 'Wow..I really like this.', '2008-05-01 09:58:50.000000', NULL, 1),
(4670537, 674473, 70661, '<td valign="top">Very nice! Love your processing!</td>', 'Very nice! Love your processing!', '2008-05-01 10:00:02.000000', NULL, 1),
(4670558, 673863, 70661, '<td valign="top">Beautiful!</td>', 'Beautiful!', '2008-05-01 10:04:49.000000', NULL, 1),
(4670569, 673324, 88254, '<td valign="top">Very light tones, good centered composition, sharp.</td>', 'Very light tones, good centered composition, sharp.', '2008-05-01 10:11:31.000000', NULL, 1),
(4670573, 674069, 88254, '<td valign="top">Picture of a picture isn''t so impressive, and the line down the middle doesn''t help.</td>', 'Picture of a picture isn''t so impressive, and the line down the middle doesn''t help.', '2008-05-01 10:11:59.000000', NULL, 1),
(4670576, 674342, 30861, '<td valign="top">This is beautiful. I love the framing of it, the two truncated bowls. there''s a beguiling flow to this image, and the textures are palpable. I hope it does well for you.</td>', 'This is beautiful. I love the framing of it, the two truncated bowls. there''s a beguiling flow to this image, and the textures are palpable. I hope it does well for you.', '2008-05-01 10:13:07.000000', NULL, 1),
(4670608, 674448, 30861, '<td valign="top">Love the title! Am wondering if this is the one that started the thread where someone commented "I liked your picture until I saw the title"? Feel free to PM me and let me know :-)</td>', 'Love the title! Am wondering if this is the one that started the thread where someone commented "I liked your picture until I saw the title"? Feel free to PM me and let me know :-)', '2008-05-01 10:22:22.000000', NULL, 1),
(4670618, 674505, 30861, '<td valign="top">Hah, someone''s hanging out in Sandwich! How come you didn''t call me for a meet ''n shoot? (snif)</td>', 'Hah, someone''s hanging out in Sandwich! How come you didn''t call me for a meet ''n shoot? (snif)', '2008-05-01 10:23:42.000000', NULL, 1),
(4670701, 674217, 65659, '<td valign="top">well... the rules state  that the photo must be taken after the challenge was made ,your photo looks like it was taken years ago .   on that note.... great job,  great photo</td>', 'well... the rules state  that the photo must be taken after the challenge was made ,your photo looks like it was taken years ago .   on that note.... great job,  great photo', '2008-05-01 10:36:47.000000', NULL, 1),
(4670847, 673450, 56828, '<td valign="top">I don''t see any sepia toning.  THere is actually quite a bit of color in this photo.  On top of that I''m not a big fan of the composition.  The lady being cut off doesn''t do any justice to the photo and the girls head behind her is sort of distracting.</td>', 'I don''t see any sepia toning.  THere is actually quite a bit of color in this photo.  On top of that I''m not a big fan of the composition.  The lady being cut off doesn''t do any justice to the photo and the girls head behind her is sort of distracting.', '2008-05-01 11:29:02.000000', NULL, 1),
(4670857, 673974, 56828, '<td valign="top">I''m not a big fan of the composition.  Both of the tires should have been completely in the photo but they are instead both cut off.</td>', 'I''m not a big fan of the composition.  Both of the tires should have been completely in the photo but they are instead both cut off.', '2008-05-01 11:31:50.000000', NULL, 1),
(4670874, 674507, 58457, '<td valign="top">nice catch of lightning... looks like a hand held shot though so the motion blur kinda hurts it.  oh well pretty exciting to catch though..</td>', 'nice catch of lightning... looks like a hand held shot though so the motion blur kinda hurts it.  oh well pretty exciting to catch though..', '2008-05-01 11:35:09.000000', NULL, 1),
(4670878, 674221, 58457, '<td valign="top">I took a couple seconds with this one.  Above view of a plastic deck chair.  For such a simple subject, very well composed.   I like it.</td>', 'I took a couple seconds with this one.  Above view of a plastic deck chair.  For such a simple subject, very well composed.   I like it.', '2008-05-01 11:36:12.000000', NULL, 1),
(4670879, 673395, 20506, '<td valign="top">Nice composition, I like the grain it adds to the nostalgia. I have used one of these once or twice although it wasn''t my own. I have 5 point''n''shoots and only just got a DSLR, I''d keep that camera if I were you. Sometimes it''s all we need to get that one, perfect, wonderful shot.</td>', 'Nice composition, I like the grain it adds to the nostalgia. I have used one of these once or twice although it wasn''t my own. I have 5 point''n''shoots and only just got a DSLR, I''d keep that camera if I were you. Sometimes it''s all we need to get that one, perfect, wonderful shot.', '2008-05-01 11:36:59.000000', NULL, 1),
(4670884, 674406, 58457, '<td valign="top">Stong capture, expression, and frozen motion.  However, I wish the open space was on the right.</td>', 'Stong capture, expression, and frozen motion.  However, I wish the open space was on the right.', '2008-05-01 11:37:55.000000', NULL, 1),
(4670886, 673624, 20506, '<td valign="top">A real sunny happy glow to this the sepia adds to the effect.</td>', 'A real sunny happy glow to this the sepia adds to the effect.', '2008-05-01 11:38:08.000000', NULL, 1),
(4670890, 674305, 20506, '<td valign="top">Frightening thought. Really emotive pic. A tad dark on my monitor though. But I think that just may add to the feel of the image.</td>', 'Frightening thought. Really emotive pic. A tad dark on my monitor though. But I think that just may add to the feel of the image.', '2008-05-01 11:40:10.000000', NULL, 1),
