(4671847, 674583, 63269, '<td valign="top">Beautiful! I like the lighting just how it is... but I wonder what might have resulted with a flash to light up the people as well, for a different variation. This shilouette style is fine though. Nice photo.</td>', 'Beautiful! I like the lighting just how it is... but I wonder what might have resulted with a flash to light up the people as well, for a different variation. This shilouette style is fine though. Nice photo.', '2008-05-01 15:23:51.000000', NULL, 1),
(4671850, 674247, 53416, '<td valign="top">Interesting idea, but I feel the overlapping subjects is distracting.  May work beter if the woman was looking towards the man?</td>', 'Interesting idea, but I feel the overlapping subjects is distracting.  May work beter if the woman was looking towards the man?', '2008-05-01 15:24:46.000000', NULL, 1),
