(4671857, 674559, 53416, '<td valign="top">Great texture and detail.  The out of focus foreground contrasts nicely with the sharp detail.  Nice!</td>', 'Great texture and detail.  The out of focus foreground contrasts nicely with the sharp detail.  Nice!', '2008-05-01 15:26:55.000000', NULL, 1),
(4671859, 673571, 5364, '<td valign="top">I really like the idea as it has a very old feel, but the parasol is too bright and all the detail is lost. It''s a pity because this would be very good.</td>', 'I really like the idea as it has a very old feel, but the parasol is too bright and all the detail is lost. It''s a pity because this would be very good.', '2008-05-01 15:27:17.000000', NULL, 1),
(4671862, 674554, 53416, '<td valign="top">Cute, interestingly lit and humourously titled!  Well done.</td>', 'Cute, interestingly lit and humourously titled!  Well done.', '2008-05-01 15:27:41.000000', NULL, 1),
(4671864, 674581, 53416, '<td valign="top">Maybe a bit too dark and gloomy?</td>', 'Maybe a bit too dark and gloomy?', '2008-05-01 15:28:22.000000', NULL, 1),
