(4676695, 673323, 5364, '<td valign="top">I like the shape and composition here, but the dark halo round the petals really puts me off.</td>', 'I like the shape and composition here, but the dark halo round the petals really puts me off.', '2008-05-03 06:51:21.000000', NULL, 1),
(4676761, 673798, 91103, '<td valign="top">I''ve looked at this many times before voting. And I can''t seem to understand why I like it so much,interesting subject,old time feel,unusual sepia tone?</td>', 'I''ve looked at this many times before voting. And I can''t seem to understand why I like it so much,interesting subject,old time feel,unusual sepia tone?', '2008-05-03 08:42:04.000000', NULL, 1),
(4676778, 674482, 39850, '<td valign="top">Nice smiling face - perhaps some tweaking in pp may have given this image an edge.  There is some visible grain, especially in her hair.</td>', 'Nice smiling face - perhaps some tweaking in pp may have given this image an edge.  There is some visible grain, especially in her hair.', '2008-05-03 09:11:17.000000', NULL, 1),
(4676782, 674473, 39850, '<td valign="top">Interesting image - almost has a lithographic type look/feel to it, which I can''t help wonder whether some tweaking in pp would have brought out even more, but then, that is if you were aiming for this type of image.  Nice - 7.</td>', 'Interesting image - almost has a lithographic type look/feel to it, which I can''t help wonder whether some tweaking in pp would have brought out even more, but then, that is if you were aiming for this type of image.  Nice - 7.', '2008-05-03 09:13:48.000000', NULL, 1),
(4676823, 673323, 92859, '<td valign="top">the flower is GORGOUS in this picture, but I would have taken off some more of the frame on the left side to help keep a focus on the flower instead of the background.</td>', 'the flower is GORGOUS in this picture, but I would have taken off some more of the frame on the left side to help keep a focus on the flower instead of the background.', '2008-05-03 09:36:50.000000', NULL, 1),
(4676824, 674478, 92859, '<td valign="top">nice contrast with the bricks, but lighten the picture up a little bit and it would make a HUGE difference.</td>', 'nice contrast with the bricks, but lighten the picture up a little bit and it would make a HUGE difference.', '2008-05-03 09:37:26.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4676920, 674406, 32025, '<td valign="top">good pic, shame the foot was just off shot :-( otherwise nice pic and tones</td>', 'good pic, shame the foot was just off shot :-( otherwise nice pic and tones', '2008-05-03 10:48:40.000000', NULL, 1),
(4676921, 672970, 32025, '<td valign="top">great comp, reflections, and subject!</td>', 'great comp, reflections, and subject!', '2008-05-03 10:49:11.000000', NULL, 1),
(4676946, 674348, 32025, '<td valign="top">Well timed! :-)</td>', 'Well timed! :-)', '2008-05-03 11:11:13.000000', NULL, 1),
(4676958, 674047, 90495, '<td valign="top">I don''t know if the black mountainside on the left serves more as a distraction   or a way to lead my eyes toward the right to the docks. I do like this shot though.</td>', 'I don''t know if the black mountainside on the left serves more as a distraction   or a way to lead my eyes toward the right to the docks. I do like this shot though.', '2008-05-03 11:30:43.000000', NULL, 1),
(4676959, 673798, 90495, '<td valign="top">I''m not particularly fond of the tone you used but I love the photograph.</td>', 'I''m not particularly fond of the tone you used but I love the photograph.', '2008-05-03 11:32:12.000000', NULL, 1),
(4677116, 673359, 77838, '<td valign="top">Aww, you have a very pretty model.  She looks so pleasant lying in the grass amongst the flowers.  I don''t actually have much of a critique for this image sorry.  -BB</td>', 'Aww, you have a very pretty model.  She looks so pleasant lying in the grass amongst the flowers.  I don''t actually have much of a critique for this image sorry.  -BB', '2008-05-03 12:46:07.000000', NULL, 1),
(4677125, 673262, 77838, '<td valign="top">I like the dark/evil sky overhead.  It feels like right out of a movie scene. -BB</td>', 'I like the dark/evil sky overhead.  It feels like right out of a movie scene. -BB', '2008-05-03 12:48:15.000000', NULL, 1),
(4677134, 674562, 77838, '<td valign="top">This feels almost too much like a B&amp;W to be sepia.  <br/> <br/>If you could''ve added a little red and taken out some blue it would''ve had just a touch more "tan/brown/sepia" color to it. -BB</td>', 'This feels almost too much like a B&W to be sepia.   If you could''ve added a little red and taken out some blue it would''ve had just a touch more "tan/brown/sepia" color to it. -BB', '2008-05-03 12:49:28.000000', NULL, 1),
(4677141, 674360, 52549, '<td valign="top">Great shot, love the toning. The title fits perfectly.</td>', 'Great shot, love the toning. The title fits perfectly.', '2008-05-03 12:51:30.000000', NULL, 1),
(4677158, 674454, 52549, '<td valign="top">A beautiful portrait and perfect in sepia. Good luck.</td>', 'A beautiful portrait and perfect in sepia. Good luck.', '2008-05-03 12:55:32.000000', NULL, 1),
(4677161, 674540, 52549, '<td valign="top">I really like this, hope it does well for you.</td>', 'I really like this, hope it does well for you.', '2008-05-03 12:56:37.000000', NULL, 1),
(4677165, 673167, 52549, '<td valign="top">Looks like an ancient film photo. Cool.</td>', 'Looks like an ancient film photo. Cool.', '2008-05-03 12:57:12.000000', NULL, 1),
(4677173, 673416, 52549, '<td valign="top">Very, very pretty.</td>', 'Very, very pretty.', '2008-05-03 12:58:44.000000', NULL, 1),
(4677212, 673450, 77838, '<td valign="top">I wish there was less color in this image.<br/> <br/>One way would be to convert to B&amp;W and then decrease the blue hue a little and increase the red also.  I like the floating viewpoint of the camera here.  It feels like it''s following you and the train. -BB</td>', 'I wish there was less color in this image. One way would be to convert to B&W and then decrease the blue hue a little and increase the red also.  I like the floating viewpoint of the camera here.  It feels like it''s following you and the train. -BB', '2008-05-03 13:06:53.000000', NULL, 1),
(4677213, 674207, 77838, '<td valign="top">This feels almost too much like a B&amp;W to be sepia.  <br/> <br/>If you could''ve added a little red and taken out some blue it would''ve had just a touch more "tan/brown/sepia" color to it. -BB</td>', 'This feels almost too much like a B&W to be sepia.   If you could''ve added a little red and taken out some blue it would''ve had just a touch more "tan/brown/sepia" color to it. -BB', '2008-05-03 13:06:58.000000', NULL, 1),
(4677214, 674179, 77838, '<td valign="top">I would''ve liked to see a little less color variation here.  Maybe to lessen the blue hue would''ve enhanced the "tan/sepia" color? -BB</td>', 'I would''ve liked to see a little less color variation here.  Maybe to lessen the blue hue would''ve enhanced the "tan/sepia" color? -BB', '2008-05-03 13:07:01.000000', NULL, 1),
(4677219, 673622, 77838, '<td valign="top">Simple but elegant!  I like the plain background here.  She seems to be lost in her own little world for the time being.  I like how she seems to be holding a necklace or locket hanging around her neck. -BB</td>', 'Simple but elegant!  I like the plain background here.  She seems to be lost in her own little world for the time being.  I like how she seems to be holding a necklace or locket hanging around her neck. -BB', '2008-05-03 13:07:49.000000', NULL, 1),
(4677220, 673173, 77838, '<td valign="top">Very nice angle to this image.  The thick border is a little distracting but the expression on their face is to die for!</td>', 'Very nice angle to this image.  The thick border is a little distracting but the expression on their face is to die for!', '2008-05-03 13:07:51.000000', NULL, 1),
(4677221, 674262, 77838, '<td valign="top">Nice dramatic tree limbs.  The clouds really give the "background" a cool look also.  Great photo. -BB</td>', 'Nice dramatic tree limbs.  The clouds really give the "background" a cool look also.  Great photo. -BB', '2008-05-03 13:07:53.000000', NULL, 1),
(4677223, 673315, 77838, '<td valign="top">I love the old wood being next to the wagon.  This is a great "sepia" photo! -BB<br/> <br/>PS.  It almost looks like the letters " V O ". (ok, mabye a little?!)</td>', 'I love the old wood being next to the wagon.  This is a great "sepia" photo! -BB PS.  It almost looks like the letters " V O ". (ok, mabye a little?!)', '2008-05-03 13:08:01.000000', NULL, 1),
(4677315, 674353, 88204, '<td valign="top">Love the shot. Not crazy about the title.</td>', 'Love the shot. Not crazy about the title.', '2008-05-03 13:43:38.000000', NULL, 1),
(4677317, 674171, 88204, '<td valign="top">Love the shot. Not sure sepia does anything for it but it doesn''t detract.</td>', 'Love the shot. Not sure sepia does anything for it but it doesn''t detract.', '2008-05-03 13:44:17.000000', NULL, 1),
(4677324, 673533, 88204, '<td valign="top">Great shot, especially the expression. Very sharp with nice smooth tones. I like the reflection of the fence on the helmet. I don''t know that sepia does anything for it. It would be just a nice in straight B&amp;W.</td>', 'Great shot, especially the expression. Very sharp with nice smooth tones. I like the reflection of the fence on the helmet. I don''t know that sepia does anything for it. It would be just a nice in straight B&W.', '2008-05-03 13:46:35.000000', NULL, 1),
(4677326, 673734, 88204, '<td valign="top">Great tones and contrast.</td>', 'Great tones and contrast.', '2008-05-03 13:47:02.000000', NULL, 1),
(4677329, 674106, 36006, '<td valign="top">Sepia??</td>', 'Sepia??', '2008-05-03 13:47:47.000000', NULL, 1),
(4677331, 673303, 88204, '<td valign="top">Sky seems like it needs a little more definition. An ND grad filter may have brought the exposure down and allowed more detail to be visible.</td>', 'Sky seems like it needs a little more definition. An ND grad filter may have brought the exposure down and allowed more detail to be visible.', '2008-05-03 13:48:23.000000', NULL, 1),
(4677332, 673881, 88204, '<td valign="top">Nice expression. Not quite sharp.</td>', 'Nice expression. Not quite sharp.', '2008-05-03 13:48:46.000000', NULL, 1),
(4677335, 673546, 88204, '<td valign="top">A little dark overall. The flowers jump out because they''re white but not much else. If you could dodge and burn you could bring down the brightness of the flowers and bring up the rest, but of course you can''t in basic editing.</td>', 'A little dark overall. The flowers jump out because they''re white but not much else. If you could dodge and burn you could bring down the brightness of the flowers and bring up the rest, but of course you can''t in basic editing.', '2008-05-03 13:49:46.000000', NULL, 1),
(4677338, 674069, 88204, '<td valign="top">It seems a little too close. If you backed up it would give me more context on what I''m seeing.</td>', 'It seems a little too close. If you backed up it would give me more context on what I''m seeing.', '2008-05-03 13:50:40.000000', NULL, 1),
(4677339, 674571, 88204, '<td valign="top">Great tones and shallow DoF.</td>', 'Great tones and shallow DoF.', '2008-05-03 13:50:55.000000', NULL, 1),
(4677340, 673450, 36006, '<td valign="top">Sepia??</td>', 'Sepia??', '2008-05-03 13:51:30.000000', NULL, 1),
(4677343, 674403, 88204, '<td valign="top">Great that you were able to catch him/her looking at you. With more editing options it would be nice if you could even out the exposure so the face is lighter and the edges of the frame are darker (of course it''s basic editing so you can''t). You almost miss the eyes because they''re so dark. Still a very nice shot.</td>', 'Great that you were able to catch him/her looking at you. With more editing options it would be nice if you could even out the exposure so the face is lighter and the edges of the frame are darker (of course it''s basic editing so you can''t). You almost miss the eyes because they''re so dark. Still a very nice shot.', '2008-05-03 13:52:54.000000', NULL, 1),
(4677347, 674376, 36006, '<td valign="top">Sepia??</td>', 'Sepia??', '2008-05-03 13:53:53.000000', NULL, 1),
(4677351, 674118, 88204, '<td valign="top">A little too orange. I think I''d like it with a little more definition in the shadows and highlights.</td>', 'A little too orange. I think I''d like it with a little more definition in the shadows and highlights.', '2008-05-03 13:54:46.000000', NULL, 1),
(4677355, 673831, 88204, '<td valign="top">Perfect subject for sepia. I like the close crop to get the point across but keep focus on details. Wood background is perfect too. Well done!</td>', 'Perfect subject for sepia. I like the close crop to get the point across but keep focus on details. Wood background is perfect too. Well done!', '2008-05-03 13:55:51.000000', NULL, 1),
