(4687541, 673708, 23484, '<td valign="top">I like the way the lighting draws you eye to one place. Good job.</td>', 'I like the way the lighting draws you eye to one place. Good job.', '2008-05-07 15:51:24.000000', NULL, 0),
(4687546, 673543, 23484, '<td valign="top">I really like the stark contrast.</td>', 'I really like the stark contrast.', '2008-05-07 15:53:16.000000', NULL, 0),
(4687579, 673923, 39218, '<td valign="top">Seems amazing to me that this came in 30th... a wonderful finish, no doubt, but should have scored so much higher!!<br/> <br/>One of the few 10''s I gave in this challenge...</td>', 'Seems amazing to me that this came in 30th... a wonderful finish, no doubt, but should have scored so much higher!! One of the few 10''s I gave in this challenge...', '2008-05-07 16:00:53.000000', NULL, 0),
(4687592, 674123, 39218, '<td valign="top">I''d love this to be in the corner of MY garden...</td>', 'I''d love this to be in the corner of MY garden...', '2008-05-07 16:03:21.000000', NULL, 0),
(4687601, 672658, 67579, '<td valign="top">both this one and the outtake are gorgeous for lack of better words :)<br/> <br/>Well done!<br/> <br/>-dave</td>', 'both this one and the outtake are gorgeous for lack of better words :) Well done! -dave', '2008-05-07 16:06:25.000000', NULL, 0),
(4687614, 672658, 44534, '<td valign="top">You did a fabulous job on this picture! I love it!  The lighting, tone and position of the model are wonderful!  A ten to me...</td>', 'You did a fabulous job on this picture! I love it!  The lighting, tone and position of the model are wonderful!  A ten to me...', '2008-05-07 16:09:26.000000', NULL, 0),
(4687624, 672658, 35545, '<td valign="top">Wonderfully retro and evocative.  I wish I had voted this challenge.</td>', 'Wonderfully retro and evocative.  I wish I had voted this challenge.', '2008-05-07 16:13:25.000000', NULL, 0),
(4687693, 672658, 81852, '<td valign="top">Both images are gorgeous! The hair clip was the only thing that gives this away as a modern portrait.  Very nicely done!  I bet there are some old family photos to compare to these. Might be fun to see the similarities over the generations.</td>', 'Both images are gorgeous! The hair clip was the only thing that gives this away as a modern portrait.  Very nicely done!  I bet there are some old family photos to compare to these. Might be fun to see the similarities over the generations.', '2008-05-07 16:31:21.000000', NULL, 0),
(4687715, 674247, 30982, '<td valign="top">You got an 8 from me as well.  Very well seen.</td>', 'You got an 8 from me as well.  Very well seen.', '2008-05-07 16:37:59.000000', NULL, 0),
(4687724, 674172, 49652, '<td valign="top">So cute!</td>', 'So cute!', '2008-05-07 16:41:17.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4687809, 674247, 50695, '<td valign="top">wow, only a 5.4. some people are dorks!<br/> <br/>great shot</td>', 'wow, only a 5.4. some people are dorks! great shot', '2008-05-07 17:14:24.000000', NULL, 0),
(4687862, 674359, 91975, '<td valign="top">i really like it, i think it''s a great photograph, unlike a lot with high ratings that is just pictures</td>', 'i really like it, i think it''s a great photograph, unlike a lot with high ratings that is just pictures', '2008-05-07 17:36:16.000000', NULL, 0),
(4687894, 674552, 54033, '<td valign="top">I do not understand how a photo like this does not get over 6.5!!<br/>Great shot.</td>', 'I do not understand how a photo like this does not get over 6.5!!Great shot.', '2008-05-07 17:51:26.000000', NULL, 0),
(4687912, 673121, 42013, '<td valign="top">Thats really cool that you self reported-- commendations to you and it won''t take you long to get back on top. It''s tough to say W/o seeing the original, but the vignette hardly seems present.<br/> <br/>It''s a lovely study of dark and light. Good work!</td>', 'Thats really cool that you self reported-- commendations to you and it won''t take you long to get back on top. It''s tough to say W/o seeing the original, but the vignette hardly seems present. It''s a lovely study of dark and light. Good work!', '2008-05-07 17:58:27.000000', NULL, 0),
(4688010, 672388, 70661, '<td valign="top">What a doll! This would be great in the soft challenge! Love it!</td>', 'What a doll! This would be great in the soft challenge! Love it!', '2008-05-07 18:45:17.000000', NULL, 0),
(4688014, 674406, 70661, '<td valign="top">Great shot Bob! I thought this might have been yours! I think you do a wonderful job on these sport action shots.</td>', 'Great shot Bob! I thought this might have been yours! I think you do a wonderful job on these sport action shots.', '2008-05-07 18:47:06.000000', NULL, 0),
(4688015, 674218, 70661, '<td valign="top">I like the moodiness of this. I gave you a 7.</td>', 'I like the moodiness of this. I gave you a 7.', '2008-05-07 18:47:59.000000', NULL, 0),
(4688017, 674282, 70661, '<td valign="top">I like this. I don''t understand why it didn''t score higher. It looks great in sepia.</td>', 'I like this. I don''t understand why it didn''t score higher. It looks great in sepia.', '2008-05-07 18:49:01.000000', NULL, 0),
(4688024, 674221, 70661, '<td valign="top">Very nice detail and it does make me want to stop and study it. I just want to take my hand and push the drops off.</td>', 'Very nice detail and it does make me want to stop and study it. I just want to take my hand and push the drops off.', '2008-05-07 18:51:50.000000', NULL, 0),
(4688031, 672732, 60915, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by timfythetoo:</b></div><hr/><i> Go figure this is yours. I seem to be connecting to your work alot lately - even not knowing its yours. So do you find locations and just hang until the right subject comes along? Were you just walking by and caught this on a whim? Is he your uncle and you made him walk by that spot 50 times to get this one shot? Brilliant shot. Glad to see it score as well as it did. Should have been higher. </i></td></tr></table> <br/> <br/>hehe thanks Tim! : )<br/> <br/>I was walking along and noticed the light on this building. Stopped and took half a dozen shots of some people walking by, then this gentleman came along and I got three shots of him. Total time spent here was less than a minute, in fact, looking at the exif data, first shot I took at 10:58:40 last shot was 10:59:15. : )<br/>Wasn''t shooting for the sepia challenge, I was just shooting...</td>', 'Originally posted by timfythetoo: Go figure this is yours. I seem to be connecting to your work alot lately - even not knowing its yours. So do you find locations and just hang until the right subject comes along? Were you just walking by and caught this on a whim? Is he your uncle and you made him walk by that spot 50 times to get this one shot? Brilliant shot. Glad to see it score as well as it did. Should have been higher.   hehe thanks Tim! : ) I was walking along and noticed the light on this building. Stopped and took half a dozen shots of some people walking by, then this gentleman came along and I got three shots of him. Total time spent here was less than a minute, in fact, looking at the exif data, first shot I took at 10:58:40 last shot was 10:59:15. : )Wasn''t shooting for the sepia challenge, I was just shooting...', '2008-05-07 18:54:56.000000', NULL, 0),
(4688072, 673345, 70661, '<td valign="top">Very peaceful and relaxing to look at. Nice.</td>', 'Very peaceful and relaxing to look at. Nice.', '2008-05-07 19:10:57.000000', NULL, 0),
(4688077, 674172, 70661, '<td valign="top">SO CUTE! I just want to hold him! Very good shot!</td>', 'SO CUTE! I just want to hold him! Very good shot!', '2008-05-07 19:11:43.000000', NULL, 0),
(4688081, 673209, 42013, '<td valign="top">nice work Nilesh! Great pair of hands. They almost seem to glow with light.</td>', 'nice work Nilesh! Great pair of hands. They almost seem to glow with light.', '2008-05-07 19:13:11.000000', NULL, 0),
(4688083, 673355, 70661, '<td valign="top">I like the blurry branches, just adds more texture and there are many!</td>', 'I like the blurry branches, just adds more texture and there are many!', '2008-05-07 19:13:30.000000', NULL, 0),
(4688085, 673859, 70661, '<td valign="top">Beautiful place and a great shot. Love the branch across the top.</td>', 'Beautiful place and a great shot. Love the branch across the top.', '2008-05-07 19:15:04.000000', NULL, 0),
(4688090, 674229, 70661, '<td valign="top">Kelly...I don''t know why this one didn''t score higher! Love it!</td>', 'Kelly...I don''t know why this one didn''t score higher! Love it!', '2008-05-07 19:17:30.000000', NULL, 0),
